fields.Can_Be_Played:
(if ((eq #page #this)
     (block 
          (sett CanPlay (and (not (WAPlayedFanFavorite #initiator))
                             (not (eq #incontrol (WAGetOwner #this)))
                             (not (eq (WAGetValue (WAGameMap) EventsPlayed)
                                      3
                                  )
                             )
                             (not (eq (WAGetValue (WAGameMap) PlayedTheRattlesnake)
                                      1
                                  )
                             )
                             (greater-eq (WAGetValue #initiator Warnings) (add (WAGetValue #target Warnings) 4))
                        )
          )
          (enum (WAGetPlayers) Playa
                (if ((eq (WAGetBaseUNID (WAGetActiveSuperstar Playa))
                         2
                     )
                     (sett CanPlay Nil)
                    )
                )
          )
          CanPlay
     )
    )
    ((and (WAInPlay #this)
          (not (eq (WAGetOwner #page)
                   (WAGetOwner #this)
               )
          )
          (not (eq (WAGetValue #this Backfired) 1))
     )
     Nil
    )
    (True True)
)

fields.Page_Played:
(if ((eq #page #this)
     (block 
          (WAAddValue (WAGameMap) NoSpecialAbilities 1)
          (WASetValue 
               (WAGameMap)
               EventsPlayed
               (add 1
                    (WAGetValue (WAGameMap) EventsPlayed)
               )
          )
          (WASetValue (WAGameMap) PlayedTheRattlesnake 1)
          (if ((greater-eq (WARandom 1 100) 80)
               (block 
                    (WADamage #initiator 15)
                    (WAStun #initiator #this 1)
                    (WASetValue #this Backfired 1)
                    (WAMessage -1 "Jim Ross: DTA," (WAGetName #initiator) "-- DON'T TRUST AUSTIN!")
               )
              )
              (True
               (block 
                    (WAMessage -1 "Jim Ross: The Rattlesnake! Austin is interrupting the match!")
                    (WAAddValue (WAGameMap) NoCommentary (WAGetTurn))
                    (sett ActiveStar (WAGetActiveSuperstar (WAGetOwner #this)))
                    (sett RunInStar (WARunIn ActiveStar 2 #this))
                    (if ((not (eq RunInStar 0))
                         (block 
                              (WAAddValue #this '$SoundPlay (WAPlaySound #this StoneColdMusic.gam 0))
                              (WAAddValue RunInStar '$RanInToHelp ActiveStar)
                              (sett CreatedPage (WACreatePageByUNID ActiveStar 425))
                              (if ((not (eq CreatedPage 0))
                                   (block 
                                        (WAAddValue #this '$RunInMove CreatedPage)
                                        (WAForcePage ActiveStar #target CreatedPage)
                                   )
                                  )
                                  (True
                                   (WAMessage -1 "Internal Error:  Could not create run in move" PlayMove)
                                  )
                              )
                         )
                        )
                    )
                    (WAWarn #initiator (WARandom 3 7))
               )
              )
          )
     )
    )
)

