          (eq #incontrol (WAGetOwner #this))
     )
     (block 
          (if ((not (eq (WAGetValue #this BrokenHold) 1))
               (WADrawPage (WAGetPlayedBy #this))
              )
          )
          (WAOutOfPlay #this)
     )
    )
    ((eq (WAGetTurn) 4)
     (block 
          (if ((not (WAInSubmissionHold (WAGetPlayedBy #this)))
               (block 
                    (sett HitWithMoveThisTurn 0)
                    (enum (WAGetConnectedMoves (WAGetPlayedBy #this)) HitMove
                          (if ((eq (WAGetTurnPlayedOn HitMove)
                                   (WAGetTurn)
                               )
                               (sett HitWithMoveThisTurn 1)
                              )
                          )
                    )
                    (if ((eq HitWithMoveThisTurn 0)
                         (block 
                              (sett JustBrokeHold 0)
                              (enum (WAPagesInPlay) IsHd
                                    (if ((and (WAIsMove IsHd)
                                              (WAHasModifier IsHd 'Hold)
                                         )
                                         (block 
                                              (WABreakHold (WAGetPlayedBy #this) 1)
                                              (sett JustBrokeHold 1)
                                         )
                                        )
                                    )
                              )
                              (if ((eq JustBrokeHold 0)
                                   (WAChangeControl)
                                  )
                              )
                              (setq HitStreak '())
                         )
                        )
                    )
               )
              )
              (True
               (enum (WAPagesInPlay) IsHold
                     (if ((and (WAIsMove IsHold)
                               (WAHasModifier IsHold 'Hold)
                          )
                          (block 
                               (WABreakHold (WAGetPlayedBy #this) 1)
                               (setq HitStreak '())
                          )
                         )
                     )
               )
              )
          )
          (WAOutOfPlay #this)
     )
    )
)

