fields.AI_AutoCounter:
(block 
     (sett Opponent (WAGetOpponent #this))
     (sett Move (WAGetProposedMove Opponent))
     (sett MyNewHP (subtract (WAGetHitPoints #this)
                          (WAGetValue Move Damage)
                   )
     )
     (sett MyStamina (divide (multiply MyNewHP 100)
                            (WAGetMaxHitPoints #this)
                     )
     )
     (sett ACPointsInHand 0)
     (enum (WAGetHand #this) PageInHand
           (if ((eq (WAGetUNID PageInHand) 165)
                (sett ACPointsInHand (add ACPointsInHand 3))
               )
               ((or (eq (WAGetUNID PageInHand) 215)
                    (eq (WAGetUNID PageInHand) 227)
                )
                (sett ACPointsInHand (add ACPointsInHand 2))
               )
           )
     )
     (sett StallTurns (count (WAGetHand #this)))
     (sett StallTurns (add StallTurns ACPointsInHand))
     (sett PagesLeft (count (WAGetPlaybook #this)))
     (sett StallTurns (add StallTurns PagesLeft))
     (sett StallTurns (divide StallTurns 7))
     (if ((or (and (WAHasModifier Move "$STUN")
                   (lesser MyStamina 50)
              )
              (lesser MyStamina 15)
              (greater-eq (WAGetTurn) (subtract (WAGetTurnLimit) StallTurns))
              (and (greater-eq (WAGetValue Move Momentum_Cost) 5)
                   (greater-eq ACPointsInHand 7)
              )
              (greater-eq (WAGetValue Move Momentum_Cost) 9)
              (greater-eq (WAGetValue Move Damage) 10)
              (and (WAHasModifier Move 'Trademark)
                   (greater-eq (WAGetValue Move Momentum_Cost) 6)
              )
              (and (eq (WAGetHitPoints Opponent) 0)
                   (not (eq (WAGetValue (WAGameMap) RefDistracted)
                            1
                        )
                   )
              )
          )
          True
         )
         (True Nil)
     )
)

