     (block 
          (sett DitchList '())
          (enum (WAGetHand #superstar) Page
                (if ((WAIsSpecial Page)
                     (sett DitchList (cons DitchList Page))
                    )
                )
          )
          (enum (WAGetInPlay #superstar) Pg
                (if ((WAIsSpecial Pg)
                     (sett DitchList (cons DitchList Pg))
                    )
                )
          )
          (if ((greater (count DitchList) 0)
               (block 
                    (sett ToDitch (item DitchList
                                        (WARandom 1 (count DitchList))
                                  )
                    )
                    (if ((WAInPlay ToDitch)
                         (block 
                              (WAOutOfPlay ToDitch)
                              (WAMessage -1 (WAGetName #this) "has removed" (WAGetName ToDitch) "from play.")
                         )
                        )
                        (True
                         (block 
                              (WAMessage (WAGetOwner #superstar) (WAGetName #this) "has forced you to ditch" (WAGetName ToDitch))
                              (WAMessage (WAGetOwner (WAGetOpponent #superstar)) (WAGetName #this) "has forced your opponent to ditch a page from hand.")
                              (sett Index (count (WAGetHand #superstar)))
                              (loop (greater Index 0)
                                    (block 
                                         (if ((eq ToDitch
                                                  (item (WAGetHand #superstar) Index)
                                              )
                                              (block 
                                                   (WADitchPage #superstar (subtract Index 1))
                                                   (sett Index 0)
                                              )
                                             )
                                         )
                                         (sett Index (subtract Index 1))
                                    )
                              )
                         )
                        )
                    )
               )
              )
          )
