                     (block 
                          (sett AlreadyInList 0)
                          (enum (OppFinishers)  InList
                                (if ((eq InList (WAGetUNID Page))
                                     (sett AlreadyInList 1)
                                    )
                                )
                          )
                          (if ((eq AlreadyInList 0)
                               (sett OppFinishers (cons OppFinishers (WAGetUNID Page)))
                              )
                          )
                     )
                    )
                )
          )
          (WAEnumPlaybook 
               #target
               IsFinisher
               '(if ((WAHasModifier IsFinisher 'Finisher)
                    (block 
                         (sett AlreadyInList 0)
                         (enum (OppFinishers)  InList
                               (if ((eq InList (WAGetUNID IsFinisher))
                                    (sett AlreadyInList 1)
                                   )
                               )
                         )
                         (if ((eq AlreadyInList 0)
                              (sett OppFinishers (cons OppFinishers (WAGetUNID IsFinisher)))
                             )
                         )
                    )
                   )
               )
          )
          (if ((greater (count OppFinishers) 0)
               (block 
