fields.Begin_Refresh:
(if ((and (eq (WAGetTurn) 25)
          (WAInPlay #this)
     )
     (block 
          (sett MyScore 0)
          (sett YourScore 0)
          (sett Me (WAGetPlayedBy #this))
          (sett You (WAGetOpponent Me))
          (sett Condition (WAStringGetValue #this User_Data))
          (if ((eq Condition "Whoever has the most pages in hand")
               (block 
                    (sett MyScore (count (WAGetHand Me)))
                    (sett YourScore (count (WAGetHand You)))
               )
              )
              ((eq Condition "Whoever has the most Momentum pages remaining in playbook")
               (block 
                    (WAEnumPlaybook 
                         Me
                         MyMom
                         '(if ((WAIsMomentum MyMom)
                              (sett MyScore (add 1 MyScore))
                             )
                         )
                    )
                    (WAEnumPlaybook 
                         You
                         YourMom
                         '(if ((WAIsMomentum YourMom)
                              (sett YourScore (add 1 YourScore))
                             )
                         )
                    )
               )
              )
              ((eq Condition "Whoever is a Genetic Anomalies employee as of June 2, 2002")
               (block 
                    (sett MyName (WAGetName (WAGetOwner Me)))
                    (sett YourName (WAGetName (WAGetOwner You)))
                    (if ((or (eq MyName "GA - Gavin")
                             (eq MyName "GA - Ian")
                             (eq MyName "GA - Mike")
                             (eq MyName "GA - Shawn")
                             (eq MyName "GA - Andy")
                             (eq MyName "GA - Anthony")
                             (eq MyName "GA - Anthony #2")
                             (eq MyName "GA - Anthony WAWF Commish")
                             (eq MyName "GA - BJ")
                             (eq MyName "GA - Michael")
                         )
                         (sett MyScore 1)
                        )
                    )
                    (if ((or (eq YourName "GA - Gavin")
                             (eq YourName "GA - Ian")
                             (eq YourName "GA - Mike")
                             (eq YourName "GA - Shawn")
                             (eq YourName "GA - Andy")
                             (eq YourName "GA - Anthony")
                             (eq YourName "GA - Anthony #2")
                             (eq YourName "GA - Anthony WAWF Commish")
                             (eq YourName "GA - BJ")
                             (eq YourName "GA - Michael")
                         )
                         (sett YourScore 1)
                        )
                    )
               )
              )
              ((eq Condition "Whoever has connected with the most different moves (by name)")
               (block 
                    (sett MyMoveList '())
                    (enum (WAGetConnectedMoves Me) MyMove
                          (block 
                               (sett IsDup 0)
                               (enum MyMoveList DupMove
                                     (if ((eq (WAGetName DupMove)
                                              (WAGetName MyMove)
                                          )
                                          (sett IsDup 1)
                                         )
                                     )
                               )
                               (if ((eq IsDup 0)
                                    (sett MyMoveList (cons MyMoveList MyMove))
                                   )
                               )
                          )
                    )
                    (sett MyScore (count MyMoveList))
                    (sett YourMoveList '())
                    (enum (WAGetConnectedMoves You) YourMove
                          (block 
                               (sett IsDup 0)
                               (enum MyMoveList DupeMove
                                     (if ((eq (WAGetName DupeMove)
                                              (WAGetName YourMove)
                                          )
                                          (sett IsDup 1)
                                         )
                                     )
                               )
                               (if ((eq IsDup 0)
                                    (sett YourMoveList (cons YourMoveList YourMove))
                                   )
                               )
                          )
                    )
                    (sett YourScore (count YourMoveList))
               )
              )
              ((eq Condition "Whoever has connected with the least moves")
               (block 
                    (sett MyScore (count (WAGetConnectedMoves You)))
                    (sett YourScore (count (WAGetConnectedMoves Me)))
               )
              )
              ((eq Condition "Whoever has the lowest Momentum total")
               (block 
                    (sett MyScore (WAGetTotalMomentum You))
                    (sett YourScore (WAGetTotalMomentum Me))
               )
              )
          )
          (WAMessage -1 (WAStringGetValue #this User_Data) "will now draw three pages.")
          (if ((greater MyScore YourScore)
               (WAMessage -1 "That player is" (WAGetName (WAGetOwner Me)))
              )
              ((greater YourScore MyScore)
               (WAMessage -1 "That player is" (WAGetName (WAGetOwner You)))
              )
              (True
               (WAMessage -1 "Both players are tied!  Everyone draws three pages.")
              )
          )
          (if ((greater-eq MyScore YourScore)
               (block 
                    (WADrawPage Me)
                    (WADrawPage Me)
                    (WADrawPage Me)
               )
              )
          )
          (if ((greater-eq YourScore MyScore)
               (block 
                    (WADrawPage You)
                    (WADrawPage You)
                    (WADrawPage You)
               )
              )
          )
     )
    )
)

