fields.Move_Connected:
(if ((eq #move #this)
     (WASetOnMat #target 1)
    )
)

fields.Damage_Bonus:
(if ((and (eq #move #this)
          (eq (WAGetTurn)
              (WAGetTurnPlayedOn #this)
          )
     )
     (WASetValue #this Submission_Damage_Bonus (add 4 (WAGetValue #this Submission_Damage_Bonus)))
    )
    (True True)
)

fields.Page_Played:
(if ((and (eq #page #this)
          (not (eq (WAGetValue #this '$CounteredMove) 0))
     )
     (WAMessage -1 "Jim Ross: Just as" (WAGetName #target) "was about to go for a" (WAGetValue #this '$CounteredMove) "," (WAGetName #initiator) "stepped in with a strong" (WAGetName #this))
    )
)

fields.Begin_Refresh:
(if ((WAInPlay #this)
     (block 
          (sett Me (WAGetPlayedBy #this))
          (sett You (WAGetOpponent Me))
          (sett MillList '())
          (sett Index 0)
          (WAEnumPlaybook 
               You
               Page
               '(block 
                    (if ((WAIsSpecial Page)
                         (sett MillList (cons MillList Index))
                        )
                    )
                    (sett Index (add Index 1))
               )
          )
          (if ((greater (count MillList) 0)
               (block 
                    (sett MillIndex (item MillList
                                          (WARandom 1 (count MillList))
                                    )
                    )
                    (WADitchFromPlaybook You MillIndex)
               )
              )
          )
     )
    )
)

fields.Move_Connected:
(if ((eq #move #this)
     (block 
          (if ((not (WAIsStunned #target))
               (WAStun #target #this 2)
              )
          )
          (WAMessage -1 "Jim Ross: There's that kick from Blackman! The Guillotine!!")
          True
     )
    )
    (True True)
)

fields.Special_Special:
(if ((eq #test 1)
     (block 
          (if ((or (eq #incontrol (WAGetOwner #this))
                   (WAIsStunned #this)
                   (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                       1
                   )
               )
               Nil
              )
              (True True)
          )
     )
    )
    ((eq #needstarget 1)
     (WAAddValue #this Target_Type 3)
    )
    (True
     (block 
          (sett DummyPage (WACreatePageByUNID #this #target))
          (sett MatchName (WAGetName DummyPage))
          (sett Index (count (WAGetHand (WAGetOpponent #this))
                      )
          )
          (sett Ditched 0)
          (loop (greater Index 0)
                (if ((eq MatchName
                         (WAGetName 
                              (item (WAGetHand (WAGetOpponent #this))
                                    Index
                              )
                         )
                     )
                     (block 
                          (WAMessage -1 "Ric Flair has forced" (WAGetName (WAGetOpponent #this)) "to bury" (WAGetName DummyPage))
                          (WAMessage -1 "Jim Ross: Ric Flair has seen everything!")
                          (WAMovePageFromHandToPlaybook (WAGetOpponent #this) (subtract Index 1) -1)
                          (sett Index 0)
                          (sett Ditched 1)
                     )
                    )
                    (True
                     (sett Index (subtract Index 1))
                    )
                )
          )
          (if ((eq Ditched 0)
               (block 
                    (sett Cmt (WARandom 1 5))
                    (if ((WAHasModifier (WAGetOpponent #this) '$Female)
                         (sett Pron "she")
                        )
                        ((WAHasModifier (WAGetOpponent #this) '$Neuter)
                         (sett Pron "it")
                        )
                        (True
                         (sett Pron "he")
                        )
                    )
                    (if ((eq Cmt 1)
                         (WAMessage -1 "Lawler: Ric Flair is a 20-plus-year veteran of this business.")
                        )
                        ((eq Cmt 2)
                         (WAMessage -1 "Jim Ross: The 53-year-old Ric Flair is trying to figure out his opponent's gameplan...")
                        )
                        ((eq Cmt 3)
                         (WAMessage -1 "Lawler: You know what, JR? It is almost as if Flair is looking through his opponent's playbook, trying to predict what" Pron "will do!")
                        )
                        ((eq Cmt 4)
                         (WAMessage -1 "Ric Flair: Whoooooooooooooo!")
                        )
                        ((eq Cmt 5)
                         (WAMessage -1 "Crowd: Whoooooooooooooo!")
                        )
                    )
               )
              )
          )
          True
     )
    )
)

fields.Get_Page_List:
(enum (WAGetHand #this) IsSpecial
      (if ((and (WAIsSpecial IsSpecial)
                (not (eq (WAGetName IsSpecial) "Crowd Support"))
                (not (eq (WAGetName IsSpecial) "Once Too Often"))
           )
           (WAAddToPageList #this (WAGetUNID IsSpecial) 0)
          )
      )
)

fields.Move_Connected:
(if ((eq #move #this)
     (block 
          (sett 50C (WARandom 1 2))
          (if ((eq 50C 1)
               (block 
                    (WASetValue #target Generic_Momentum (subtract (WAGetValue #target Generic_Momentum) 1))
                    (WAMessage -1 "Jim Ross: What a takedown!!")
                    (WADitchFromPlaybook #target)
               )
              )
          )
          True
     )
    )
    (True True)
)

(if ((eq #move #this)
     (block 
          (if ((not (WAIsStunned #target))
               (WAStun #target #this 2)
              )
          )
          (sett ConnectedWith 0)
          (enum (WAGetConnectedMoves #superstar) IsThis
                (if ((and (eq (WAGetName IsThis)
                              (WAGetName #this)
                          )
                          (not (eq IsThis #this))
                     )
                     (sett ConnectedWith (add 1 ConnectedWith))
                    )
                )
          )
          (if ((eq ConnectedWith 0)
               (block 
                    (WAMessage -1 "Lawler: Woah!")
                    (WAMessage -1 "Jim Ross:" (WAGetName #superstar) "with a Chokeslam all the way to Hell!")
               )
              )
              ((lesser ConnectedWith 4)
               (WAMessage -1 "Jim Ross:" (WAGetName #superstar) "with ANOTHER Chokeslam! I can't believe it!")
              )
              (True
               (block 
                    (WAMessage -1 "Jim Ross: Five Chokeslams! Someone's got to stop the match!!")
                    (WAMessage -1 "Lawler: You might be right about that JR, enough is enough...")
               )
              )
          )
          True
     )
    )
    (True True)
)

(if ((eq #move #this)
     (block 
          (if ((WAHasModifier #superstar '$Female)
               (sett Pron "she's")
              )
              ((WAHasModifier #superstar '$Neuter)
               (sett Pron "it's")
              )
              (True
               (sett Pron "he's")
              )
          )
          (if ((WAHasModifier #target '$Female)
               (sett Pron2 "she")
              )
              ((WAHasModifier #target '$Neuter)
               (sett Pron2 "it")
              )
              (True
               (sett Pron2 "he")
              )
          )
          (WAMessage -1 "Jim Ross: It's Ric Flair's Figure Four! And by God," Pron "got it cinched in!")
          (WAMessage -1 "Lawler: Will" (WAGetName #target) "tap? Can" Pron2 "withstand the pain?")
     )
    )
)

fields.Damage_Bonus:
(if ((eq #move #this)
     (block 
          (sett Bonus (WAGetValue (WAGetPlayedBy #this) Generic_Momentum))
          (if ((greater Bonus 5)
               (sett Bonus 5)
              )
          )
          (WASetValue #move Damage_Bonus (add (WAGetValue #move Damage_Bonus) Bonus))
     )
    )
    (True True)
)
